// ============================================
// FINAL GUARDRAIL — RETENTION DECISION
// ============================================

// ---------- CONFIGURATION ----------
const MAX_DISCOUNT_PERCENT = 20;
const MIN_DISCOUNT_PERCENT = 0;
const MIN_MONTHLY_PRICE = 0;


// ---------- HELPERS ----------
function parseJSON(value) {
  if (typeof value === "object" && value !== null) {
    return value;
  }

  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch (e) {
      return null;
    }
  }

  return null;
}


// ---------- INPUT ----------
const finalDecision = parseJSON($json);


// ---------- RESULTS ----------
const errors = [];
const warnings = [];


// ============================================
// 1. BASIC STRUCTURE CHECK
// ============================================

if (!finalDecision) {
  errors.push(
    "Final Decision output is not valid JSON."
  );
}

const validDecisions = [
  "SELECT",
  "MODIFY",
  "REJECT_ALL"
];

if (
  finalDecision &&
  !validDecisions.includes(finalDecision.decision)
) {
  errors.push(
    "Decision must be SELECT, MODIFY, or REJECT_ALL."
  );
}


// ============================================
// 2. REQUIRED FIELDS
// ============================================

if (finalDecision) {

  if (!finalDecision.selected_strategy) {
    errors.push(
      "selected_strategy is missing."
    );
  }

  if (!finalDecision.decision_reason) {
    errors.push(
      "decision_reason is missing."
    );
  }

  if (!finalDecision.customer_problem_addressed) {
    errors.push(
      "customer_problem_addressed is missing."
    );
  }

  if (!finalDecision.expected_customer_value) {
    errors.push(
      "expected_customer_value is missing."
    );
  }

  if (!finalDecision.expected_business_value) {
    errors.push(
      "expected_business_value is missing."
    );
  }

  if (!finalDecision.key_risk) {
    errors.push(
      "key_risk is missing."
    );
  }

  if (
    !Array.isArray(finalDecision.evidence_basis) ||
    finalDecision.evidence_basis.length === 0
  ) {
    errors.push(
      "evidence_basis is missing or empty."
    );
  }
}


// ============================================
// 3. SELECT LOGIC
// ============================================

if (
  finalDecision &&
  finalDecision.decision === "SELECT"
) {

  if (
    !finalDecision.selected_strategy?.modification ||
    finalDecision.selected_strategy.modification !== "None"
  ) {
    errors.push(
      "SELECT decision must have modification = None."
    );
  }
}


// ============================================
// 4. MODIFY LOGIC
// ============================================

if (
  finalDecision &&
  finalDecision.decision === "MODIFY"
) {

  // Only require that a modification exists.
  // DO NOT check strategy name.
  // DO NOT check priority.
  // DO NOT compare with Retention Strategy Agent.

  if (
    !finalDecision.selected_strategy?.modification ||
    finalDecision.selected_strategy.modification === "None"
  ) {
    errors.push(
      "MODIFY decision must contain a modification."
    );
  }
}


// ============================================
// 5. REJECT_ALL LOGIC
// ============================================

if (
  finalDecision &&
  finalDecision.decision === "REJECT_ALL"
) {

  const selected =
    finalDecision.selected_strategy;

  if (selected?.strategy_name !== "None") {
    errors.push(
      "REJECT_ALL must have strategy_name = None."
    );
  }

  if (selected?.priority !== 0) {
    errors.push(
      "REJECT_ALL must have priority = 0."
    );
  }

  if (selected?.original_strategy !== "None") {
    errors.push(
      "REJECT_ALL must have original_strategy = None."
    );
  }

  if (selected?.modification !== "None") {
    errors.push(
      "REJECT_ALL must have modification = None."
    );
  }
}


// ============================================
// 6. DISCOUNT CHECK
// ============================================

let fullText = "";

if (finalDecision) {
  fullText = JSON.stringify(finalDecision);
}


// Detect:
// 10% discount
// 10% off
// 10 percent discount
// discount of 10%
// 10% reduction

const discountRegex =
  /(\d+(?:\.\d+)?)\s*(?:%|percent)\s*(?:discount|off|reduction)?|(?:discount|reduction)\s*(?:of)?\s*(\d+(?:\.\d+)?)\s*(?:%|percent)/gi;

const discountValues = [];

for (
  const match of fullText.matchAll(discountRegex)
) {

  const value =
    match[1] || match[2];

  if (value !== undefined) {
    discountValues.push(Number(value));
  }
}


for (const discount of discountValues) {

  if (discount < MIN_DISCOUNT_PERCENT) {
    errors.push(
      `Invalid discount: ${discount}%. Discount cannot be negative.`
    );
  }

  if (discount > MAX_DISCOUNT_PERCENT) {
    errors.push(
      `Discount of ${discount}% exceeds the maximum allowed discount of ${MAX_DISCOUNT_PERCENT}%.`
    );
  }
}


// ============================================
// 7. MONTHLY PRICE CHECK
// ============================================

const priceRegex =
  /\$?\s*(\d+(?:\.\d+)?)\s*(?:\/\s*month|per\s+month)/gi;

const prices = [];

for (
  const match of fullText.matchAll(priceRegex)
) {
  prices.push(Number(match[1]));
}


for (const price of prices) {

  if (price < MIN_MONTHLY_PRICE) {
    errors.push(
      `Invalid monthly price: ${price}. Monthly price cannot be negative.`
    );
  }
}


// ============================================
// 8. FLAG UNSUPPORTED INCENTIVES
// ============================================

const incentivePatterns = [
  /\bfree\b/gi,
  /\bcomplimentary\b/gi,
  /\bone[- ]time incentive\b/gi,
  /\bcashback\b/gi,
  /\bgift card\b/gi,
  /\bdevice upgrade\b/gi
];


for (const pattern of incentivePatterns) {

  if (pattern.test(fullText)) {
    warnings.push(
      "Potentially unsupported incentive detected. Verify that the proposed incentive is actually available."
    );
  }
}


// ============================================
// 9. FLAG OVERCONFIDENT ASSUMPTIONS
// ============================================

const assumptionPatterns = [
  /\bguaranteed\b/gi,
  /\bwill definitely\b/gi,
  /\bwill churn\b/gi,
  /\bwill accept\b/gi,
  /\bcertain to\b/gi
];


for (const pattern of assumptionPatterns) {

  if (pattern.test(fullText)) {
    warnings.push(
      "Potentially overconfident customer assumption detected."
    );
  }
}


// ============================================
// 10. CONFIDENCE CHECK
// ============================================

if (
  finalDecision &&
  !["HIGH", "MEDIUM", "LOW"].includes(
    finalDecision.decision_confidence
  )
) {
  errors.push(
    "decision_confidence must be HIGH, MEDIUM, or LOW."
  );
}


// ============================================
// FINAL RESULT
// ============================================

const passed =
  errors.length === 0;


return [
  {
    json: {

      guardrail_status:
        passed ? "PASS" : "FAIL",

      decision_valid:
        passed,

      errors,

      warnings,

      checks: {
        max_discount_percent:
          MAX_DISCOUNT_PERCENT,

        discount_values_detected:
          discountValues,

        monthly_prices_detected:
          prices
      },

      final_decision:
        finalDecision
    }
  }
];

