const items = $input.all();

let risk = null;
let painPoints = null;

for (const item of items) {
  const data = item.json;

  // Identify Risk Agent output
  if (data.risk_assessment) {
    risk = {
      churn_score: data.risk_assessment.churn_score,
      risk_band: data.risk_assessment.risk_band,
      overall_interpretation: data.risk_assessment.overall_interpretation,
      risk_signals: (data.risk_signals || []).map(x => ({
        signal: x.signal,
        importance: x.importance,
        evidence: x.evidence
      })),
      protective_signals: (data.protective_signals || []).map(x => ({
        signal: x.signal,
        evidence: x.evidence
      })),
      risk_interactions: (data.risk_interactions || []).map(x => ({
        observation: x.observation,
        interpretation: x.interpretation
      })),
      confidence: data.confidence
    };
  }

  // Identify Pain Point Agent output
  if (data.potential_pain_points) {
    painPoints = {
      primary_potential_need: data.primary_potential_need,
      secondary_potential_needs: data.secondary_potential_needs,
      potential_pain_points: (data.potential_pain_points || []).map(x => ({
        pain_point: x.pain_point,
        priority: x.priority,
        confidence: x.confidence,
        evidence: x.evidence
      })),
      alternative_explanations: data.alternative_explanations,
      unknowns: data.unknowns,
      overall_confidence: data.overall_confidence
    };
  }
}

return [
  {
    json: {
      risk,
      pain_points: painPoints
    }
  }
];

